import 'package:flutter/material.dart';

/// 设备形态：手机与平板使用不同的导航与栅格策略。
enum FormFactor { phone, tablet }

class Breakpoints {
  /// 最短边达到该值按平板处理，避免 iPhone 横屏被误判为平板。
  static const double tabletShortestSide = 600;

  /// 内容区宽度达到该值使用两列卡片。
  static const double twoColumn = 640;

  /// 内容区宽度达到该值报告页左右分栏。
  static const double twoPane = 900;

  /// 内容区宽度达到该值使用三列卡片。
  static const double threeColumn = 1080;

  /// 平板宽度达到该值展开侧边导航（显示文字）。
  static const double extendedRail = 1200;

  static const double contentMax = 1200;
  static const double formMax = 720;
  static const double listMax = 1000;
}

FormFactor formFactorOf(Size size) =>
    size.shortestSide >= Breakpoints.tabletShortestSide
    ? FormFactor.tablet
    : FormFactor.phone;

bool isTabletSize(Size size) => formFactorOf(size) == FormFactor.tablet;

bool isTablet(BuildContext context) => isTabletSize(MediaQuery.sizeOf(context));

/// 根据内容区可用宽度返回卡片列数。
int gridColumns(double width) {
  if (width >= Breakpoints.threeColumn) return 3;
  if (width >= Breakpoints.twoColumn) return 2;
  return 1;
}

/// 居中并限制最大宽度，避免平板/横屏内容被拉伸。
class ContentFrame extends StatelessWidget {
  const ContentFrame({
    super.key,
    required this.child,
    this.maxWidth = Breakpoints.contentMax,
    this.padding = EdgeInsets.zero,
  });

  final Widget child;
  final double maxWidth;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: maxWidth),
        child: Padding(padding: padding, child: child),
      ),
    );
  }
}

import 'package:flutter/material.dart';

import 'adaptive.dart';

class AdaptiveNavItem {
  const AdaptiveNavItem({required this.icon, required this.label});

  final IconData icon;
  final String label;
}

/// 统一导航骨架：
/// - 手机（含横屏、分屏窄窗口）：底部 NavigationBar；
/// - 平板：侧边 NavigationRail，宽度足够时展开显示文字。
class AdaptiveShell extends StatelessWidget {
  const AdaptiveShell({
    super.key,
    required this.appBar,
    required this.body,
    required this.items,
    required this.selectedIndex,
    required this.onSelected,
  });

  final PreferredSizeWidget appBar;
  final Widget body;
  final List<AdaptiveNavItem> items;
  final int selectedIndex;
  final ValueChanged<int> onSelected;

  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    if (!isTabletSize(size)) {
      return Scaffold(
        appBar: appBar,
        body: body,
        bottomNavigationBar: NavigationBar(
          selectedIndex: selectedIndex,
          onDestinationSelected: onSelected,
          destinations: [
            for (final item in items)
              NavigationDestination(icon: Icon(item.icon), label: item.label),
          ],
        ),
      );
    }

    final extended = size.width >= Breakpoints.extendedRail;
    return Scaffold(
      appBar: appBar,
      body: Row(
        children: [
          NavigationRail(
            extended: extended,
            selectedIndex: selectedIndex,
            labelType: extended
                ? NavigationRailLabelType.none
                : NavigationRailLabelType.all,
            onDestinationSelected: onSelected,
            destinations: [
              for (final item in items)
                NavigationRailDestination(
                  icon: Icon(item.icon),
                  label: Text(item.label),
                ),
            ],
          ),
          const VerticalDivider(width: 1),
          Expanded(child: body),
        ],
      ),
    );
  }
}

